def shifted(name,t):
    dr,dc=t
    return {(r+dr,c+dc):v for (r,c),v in objs[name].items()}
def compatible(new,occupied):
    return all(p not in occupied or (occupied[p]==2 and v==2) for p,v in new.items())
solutions=[]
def dfs(place):
    if len(place)==len(objs):
        allcells={}
        for n,t in place.items(): allcells.update(shifted(n,t))
        rs=[r for r,c in allcells];cs=[c for r,c in allcells]
        area=(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
        solutions.append((area,place.copy()))
        return
    occ={}
    for n,t in place.items():
        for p,v in shifted(n,t).items():occ[p]=v
    redplaced=[p for p,v in occ.items() if v==2]
    for name in objs:
        if name in place:continue
        seen=set()
        for rr,cc in reds[name]:
            for pr,pc in redplaced:
                t=(pr-rr,pc-cc)
                if t in seen:continue
                seen.add(t)
                new=shifted(name,t)
                if compatible(new,occ):
                    # count connections
                    place[name]=t;dfs(place);del place[name]
dfs(base)
len(solutions),sorted(set(x[0] for x in solutions))[:20]

